// static
bool PrefsStubDispatch::Accept(
    Prefs* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kPrefs_GetPref_Name: {
      break;
    }
    case internal::kPrefs_GetExtensionPrefWithControl_Name: {
      break;
    }
    case internal::kPrefs_SetPref_Name: {
      break;
    }
    case internal::kPrefs_ClearExtensionControlledPref_Name: {
      break;
    }
    case internal::kPrefs_AddObserver_Name: {

      DCHECK(message->is_serialized());
      internal::Prefs_AddObserver_Params_Data* params =
          reinterpret_cast<internal::Prefs_AddObserver_Params_Data*>(
              message->mutable_payload());
      
      
      // Validation for Prefs.2
      bool success = true;
      PrefPath p_path{};
      ::mojo::PendingRemote<PrefObserver> p_observer{};
      Prefs_AddObserver_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadPath(&p_path))
        success = false;
      if (success) {
        p_observer =
            input_data_view.TakeObserver<decltype(p_observer)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Prefs::Name_, 2, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->AddObserver(        
        std::move(p_path), 
        std::move(p_observer));
      return true;
    }
  }
  return false;
}

